// Move claudinite-dashboard's flat modules into src/<layer>/ and tooling/, and
// recompute every relative reference — module specifiers, markdown links in
// comments and docs, the html entry — from each file's new home.
import { readdir, readFile, writeFile, stat } from 'node:fs/promises';
import { join, dirname, relative, normalize, posix } from 'node:path';
import { execFileSync } from 'node:child_process';

const PACK = '/home/user/claudinite/packs/claudinite-dashboard';

const DERIVE = ['model', 'activity', 'work', 'next-work', 'fleet', 'fleet-ledger',
  'repo-ledger', 'fleet-growth', 'board', 'explore', 'pricing'];
const READ = ['github', 'cache', 'auth', 'config', 'budget', 'fleet-sweep', 'usage',
  'contributions', 'canon', 'settings-read'];
const RENDER = ['ui', 'sheet', 'board-view', 'contrib-view'];
const VIEWS = ['view-fleet', 'view-repo'];
const TOOLING = ['serve', 'build-site', 'deployment-config', 'oauth-exchange'];

const MAP = new Map();                       // old pack-relative -> new pack-relative
MAP.set('app.mjs', 'src/app.mjs');
for (const n of DERIVE) MAP.set(`${n}.mjs`, `src/derive/${n}.mjs`);
for (const n of READ) MAP.set(`${n}.mjs`, `src/read/${n}.mjs`);
for (const n of RENDER) MAP.set(`${n}.mjs`, `src/render/${n}.mjs`);
for (const n of VIEWS) MAP.set(`${n}.mjs`, `src/views/${n}.mjs`);
for (const n of TOOLING) MAP.set(`${n}.mjs`, `tooling/${n}.mjs`);

const newPath = (p) => MAP.get(p) ?? p;      // identity for everything that stays

async function walk(dir, acc = []) {
  for (const e of await readdir(dir, { withFileTypes: true })) {
    if (e.name === '.git') continue;
    const full = join(dir, e.name);
    if (e.isDirectory()) await walk(full, acc); else acc.push(full);
  }
  return acc;
}

// Resolve a relative reference from a pack-relative file to a pack-relative target;
// null when it leaves the pack (those specifiers are rewritten by depth instead).
function target(fromRel, spec) {
  const t = posix.normalize(posix.join(posix.dirname(fromRel), spec));
  return t.startsWith('..') ? null : t;
}

// The specifier that gets you from `fromRel`'s directory to `toRel`.
function specFor(fromRel, toRel) {
  let s = posix.relative(posix.dirname(fromRel), toRel);
  return s.startsWith('.') ? s : `./${s}`;
}

// A reference that leaves the pack keeps its target; only the climb changes.
function outward(oldFromRel, newFromRel, spec) {
  const abs = posix.normalize(posix.join(posix.dirname(oldFromRel), spec)); // e.g. ../claudinite-tasks/x
  const up = (abs.match(/^(\.\.\/)+/) ?? [''])[0];
  const rest = abs.slice(up.length);
  const extra = posix.dirname(newFromRel).split('/').filter((x) => x !== '.').length
    - posix.dirname(oldFromRel).split('/').filter((x) => x !== '.').length;
