mkdir -p src && git mv index.html src/index.html && echo "moved"
python3 - <<'PY'
import pathlib

# --- serve.mjs: a directory request finds the page where it lives -------------------
p = pathlib.Path('tooling/serve.mjs'); s = p.read_text()
old = "  const file = path.endsWith('/') ? join(target, 'index.html') : target;"
new = """  // THE PAGE LIVES UNDER `src/` AND IS SERVED FROM THE DIRECTORY ABOVE IT. An HTML
  // `src=` resolves against the document's URL, so the page's own script tag names
  // `./src/app.mjs` — true at the URL it is served from, not at the path it is stored
  // at. Serving it anywhere else would break every module it loads, so a directory
  // request tries the directory's own index first and then the one `src/` holds.
  const candidates = path.endsWith('/')
    ? [join(target, 'index.html'), join(target, 'src/index.html')]
    : [target];"""
assert old in s
s = s.replace(old, new)
old2 = """  try {
    const info = await stat(file);
    if (!info.isFile()) throw new Error('not a file');"""
new2 = """  try {
    const file = (await Promise.all(candidates.map(async (c) => {
      try { return (await stat(c)).isFile() ? c : null; } catch { return null; }
    }))).find(Boolean);
    if (!file) throw new Error('not a file');"""
assert old2 in s
s = s.replace(old2, new2)
p.write_text(s)
print('serve.mjs taught the relocation')
PY
grep -n "candidates\|const file" tooling/serve.mjs | head

